          "kind": "fact",
          "text": "A job cut off by a stop is unfinished, not done."
        },
        {
          "kind": "fact",
          "text": "After a restart, the same step runs again on the same head."
        },
        {
          "kind": "fact",
          "text": "A job whose head moved is closed as superseded."
        }
      ],
      "why": [
        {
          "kind": "fact",
          "text": "A restart left jobs uncertain and blocked their tasks for hours."
        },
        {
          "kind": "fact",
          "text": "Marking them done by hand hid the missing step."
        }
      ],
      "scope_in": [
        "the autopilot loop",
        "its tests"
      ],
      "scope_out": [
        "worker and reviewer rounds"
      ],
      "done": [
        {
          "kind": "fact",
          "text": "Intent 1: a test shows no job is marked done after a stop."
        },
        {
          "kind": "fact",
          "text": "Intent 2: a test shows the gate runs again and the review starts."
        },
        {
          "kind": "fact",
          "text": "Intent 3: a test shows a moved head closes the old job."
        }
      ],
      "notes": [
